package com.atlasiq.security;
import com.atlasiq.qir.*;import com.fasterxml.jackson.databind.*;import jakarta.enterprise.context.ApplicationScoped;import java.nio.file.*;import java.util.*;
@ApplicationScoped public class LockfileDependencyParser {private final ObjectMapper json=new ObjectMapper();public Result parse(Path root){List<QirNode> nodes=new ArrayList<>();List<QirEdge> edges=new ArrayList<>();Path lock=root.resolve("package-lock.json");if(!Files.isRegularFile(lock))return new Result(List.of(),List.of());try{JsonNode packages=json.readTree(lock.toFile()).path("packages");packages.fields().forEachRemaining(e->{String path=e.getKey(),name=e.getValue().path("name").asText("");if(name.isBlank()&&path.startsWith("node_modules/"))name=path.substring("node_modules/".length());String version=e.getValue().path("version").asText("");if(name.isBlank()||version.isBlank())return;String id="package:npm:"+name+"@"+version;nodes.add(new QirNode(id,"software-package",name,"npm",Map.of("version",version,"ecosystem","npm","transitive",!path.isBlank(),"evidenceFile","package-lock.json")));e.getValue().path("dependencies").fieldNames().forEachRemaining(dep->edges.add(new QirEdge(id,"package:npm:"+dep,"depends_on",Map.of("scope","supply-chain","evidenceFile","package-lock.json"))));});}catch(Exception ignored){}return new Result(List.copyOf(nodes),List.copyOf(edges));}public record Result(List<QirNode> nodes,List<QirEdge> edges){}
}